import { Controller } from '@nestjs/common';

// 이 기능(FN-SFR-032-02)은 화면만 만든다.
// POST /attendance-requests, GET /attendance-requests 는 다른 기능이 만든 API를 함께 쓴다.
@Controller('api/v1')
export class FnSfr03202Controller {}

