import { useState } from 'react';
import {
  call,
  useData,
  Badge,
  DateText,
  Filters,
  Band,
  DataTable,
  Pager,
  Drawer,
  Pairs,
  Tiles,
  Form,
  Field,
  TextInput,
  DateInput,
  Select,
  LookupSelect,
  RefName,
} from '../kit';
import type { PageProps, Row, Page, Column } from '../kit';

const SIZE = 20;

const STATUSES: [string, string][] = [
  ['기안', '기안'],
  ['결재대기', '결재대기'],
  ['진행중', '진행중'],
  ['승인', '승인'],
  ['보류', '보류'],
  ['반려', '반려'],
  ['회수', '회수'],
  ['완료', '완료'],
];

const TRIP_CATEGORIES: [string, string][] = [
  ['출장', '출장'],
  ['외근', '외근'],
];

export default function FnSfr03202Page({ role, notify }: PageProps) {
  const [employeeId, setEmployeeId] = useState<number | string>('');
  const [typeId, setTypeId] = useState<number | string>('');
  const [status, setStatus] = useState('');
  const [applied, setApplied] = useState<Row>({});
  const [page, setPage] = useState(0);
  const [detail, setDetail] = useState<Row | null>(null);
  const [creating, setCreating] = useState(false);

  const [fType, setFType] = useState<number | string>('');
  const [fStart, setFStart] = useState('');
  const [fEnd, setFEnd] = useState('');
  const [fReason, setFReason] = useState('');
  const [fWorkTime, setFWorkTime] = useState('');
  const [fTripCategory, setFTripCategory] = useState('');
  const [fTripPlace, setFTripPlace] = useState('');
  const [fAttachment, setFAttachment] = useState('');

  const { data, error, loading, reload } = useData<Page>(
    () => call<Page>('GET', '/attendance-requests', role, undefined, { ...applied, page, size: SIZE }),
    [applied, page, role],
  );

  const items = data ? data.items : [];
  const total = data ? data.total : 0;
  const waiting = items.filter((r) => r['approvalStatus'] === '결재대기' || r['approvalStatus'] === '진행중');
  const approved = items.filter((r) => r['approvalStatus'] === '승인' || r['approvalStatus'] === '완료');

  function search() {
    setPage(0);
    setApplied({ employeeId, attendanceTypeId: typeId, approvalStatus: status });
  }

  function reset() {
    setEmployeeId('');
    setTypeId('');
    setStatus('');
    setPage(0);
    setApplied({});
  }

  function openCreate() {
    setFType('');
    setFStart('');
    setFEnd('');
    setFReason('');
    setFWorkTime('');
    setFTripCategory('');
    setFTripPlace('');
    setFAttachment('');
    setCreating(true);
  }

  async function submit() {
    if (fType === '' || !fStart || !fEnd) {
      throw new Error('근태항목, 시작일, 종료일을 입력해 주세요.');
    }
    if (fEnd < fStart) {
      throw new Error('종료일은 시작일보다 빠를 수 없습니다.');
    }
    const body: Row = {
      attendanceTypeId: fType,
      startDate: fStart,
      endDate: fEnd,
    };
    if (fReason) body['reason'] = fReason;
    if (fWorkTime) body['changedWorkTime'] = fWorkTime;
    if (fTripCategory) body['tripCategory'] = fTripCategory;
    if (fTripPlace) body['tripPlace'] = fTripPlace;
    if (fAttachment) body['attachment'] = fAttachment;
    await call('POST', '/attendance-requests', role, body);
    notify('근태 신청을 등록하고 결재를 상신했습니다.');
    setCreating(false);
    setPage(0);
    reload();
  }

  const columns: Column[] = [
    { key: 'employeeId', label: '신청자', render: (r) => <RefName table="employee" role={role} value={r['employeeId']} /> },
    { key: 'attendanceTypeId', label: '근태항목', render: (r) => <RefName table="attendance_type" role={role} value={r['attendanceTypeId']} /> },
    { key: 'startDate', label: '시작일', render: (r) => <DateText value={r['startDate']} /> },
    { key: 'endDate', label: '종료일', render: (r) => <DateText value={r['endDate']} /> },
    { key: 'approvalStatus', label: '결재 진행 상태', render: (r) => <Badge value={r['approvalStatus']} /> },
  ];

  return (
    <div className="bento">
      <section className="box span-12">
        <h2>신청 현황</h2>
        <Tiles
          items={[
            ['조회 건수', total],
            ['결재 진행 (현재 쪽)', waiting.length],
            ['승인·완료 (현재 쪽)', approved.length],
          ]}
        />
      </section>

      <section className="box span-8">
        <h2>근태 신청 목록</h2>
        <Filters onSearch={search} onReset={reset}>
          <Field label="신청자">
            <LookupSelect table="employee" role={role} value={employeeId} onChange={setEmployeeId} placeholder="전체" />
          </Field>
          <Field label="근태항목">
            <LookupSelect table="attendance_type" role={role} value={typeId} onChange={setTypeId} placeholder="전체" />
          </Field>
          <Field label="결재 진행 상태">
            <Select value={status} onChange={setStatus} options={STATUSES} placeholder="전체" />
          </Field>
        </Filters>
        <Band total={total}>
          <button type="button" onClick={openCreate}>근태 신청</button>
        </Band>
        {error ? <div className="error">{error}</div> : null}
        <DataTable
          columns={columns}
          rows={items}
          onRowClick={(r) => setDetail(r)}
          empty={loading ? '불러오는 중입니다.' : '조회된 근태 신청이 없습니다.'}
        />
        <Pager page={page} size={SIZE} total={total} onPage={setPage} />
      </section>

      <section className="box span-4">
        <h2>처리 대기</h2>
        {waiting.length === 0 ? (
          <p>결재 진행 중인 신청이 없습니다.</p>
        ) : (
          <ul>
            {waiting.map((r) => (
              <li key={String(r['attendanceRequestId'])}>
                <RefName table="employee" role={role} value={r['employeeId']} />
                {' '}
                <RefName table="attendance_type" role={role} value={r['attendanceTypeId']} />
                {' '}
                <Badge value={r['approvalStatus']} />
              </li>
            ))}
          </ul>
        )}
      </section>

      {detail ? (
        <Drawer title="근태 신청 상세" onClose={() => setDetail(null)}>
          <Pairs
            items={[
              ['근태 신청 ID', String(detail['attendanceRequestId'] ?? '')],
              ['신청자', <RefName table="employee" role={role} value={detail['employeeId']} />],
              ['근태항목', <RefName table="attendance_type" role={role} value={detail['attendanceTypeId']} />],
              ['시작일', <DateText value={detail['startDate']} />],
              ['종료일', <DateText value={detail['endDate']} />],
              ['사유', String(detail['reason'] ?? '')],
              ['결재 진행 상태', <Badge value={detail['approvalStatus']} />],
            ]}
          />
        </Drawer>
      ) : null}

      {creating ? (
        <Drawer title="근태 신청" onClose={() => setCreating(false)}>
          <Form onSubmit={submit} submit="신청 및 상신">
            <Field label="근태항목" required>
              <LookupSelect table="attendance_type" role={role} value={fType} onChange={setFType} />
            </Field>
            <Field label="시작일" required>
              <DateInput value={fStart} onChange={setFStart} />
            </Field>
            <Field label="종료일" required>
              <DateInput value={fEnd} onChange={setFEnd} />
            </Field>
            <Field label="사유" wide>
              <TextInput value={fReason} onChange={setFReason} multiline />
            </Field>
            <Field label="변경 근무시간">
              <TextInput value={fWorkTime} onChange={setFWorkTime} />
            </Field>
            <Field label="출장·외근 구분">
              <Select value={fTripCategory} onChange={setFTripCategory} options={TRIP_CATEGORIES} />
            </Field>
            <Field label="장소">
              <TextInput value={fTripPlace} onChange={setFTripPlace} />
            </Field>
            <Field label="증빙 첨부파일">
              <TextInput value={fAttachment} onChange={setFAttachment} />
            </Field>
          </Form>
        </Drawer>
      ) : null}
    </div>
  );
}
